insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000005', 'en', null, 'Introduction to Physics', 'A first tour of how the physical world works — measuring quantities, describing motion, and tracing forces, energy, and momentum through everyday events. Structure adapted from OpenStax College Physics 2e (CC BY 4.0).', null, 'foundations', 5, true, 'science', '{}')
