insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000005', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The SI base unit of mass is the…","options":["kilogram","gram","newton","pound"],"answer":0,"explanation":"Mass is measured in kilograms (kg); the newton is a unit of force — see ''Units & measurement''."},{"prompt":"Velocity is best described as…","options":["the total distance traveled","the rate of change of position, with direction","a push or a pull","mass multiplied by speed"],"answer":1,"explanation":"Velocity is displacement per unit time and includes direction — see ''Describing motion''."},{"prompt":"Newton''s second law is written as…","options":["F = m/a","F = ma","F = mv","a = F·m"],"answer":1,"explanation":"Net force equals mass times acceleration — see ''Forces & Newton''s laws''."},{"prompt":"The kinetic energy of a moving object is…","options":["m·v","m·g·h","(1/2)·m·v^2","F·t"],"answer":2,"explanation":"Kinetic energy is one-half mass times speed squared — see ''Energy & work''."},{"prompt":"Momentum is defined as…","options":["force times time","one-half mass times velocity squared","force times distance","mass times velocity"],"answer":3,"explanation":"Momentum p = m·v — see ''Momentum''."},{"prompt":"Sound travels through air as…","options":["an electromagnetic wave","a mechanical (pressure) wave","a beam of light","a stationary charge"],"answer":1,"explanation":"Sound is a mechanical wave — vibrating air pressure — unlike light, which is electromagnetic."},{"prompt":"Electric current is measured in…","options":["volts","ohms","amperes","watts"],"answer":2,"explanation":"Current (rate of charge flow) is measured in amperes (A)."},{"prompt":"Near Earth''s surface, the acceleration due to gravity is about…","options":["1.0 m/s^2","0.98 m/s^2","98 m/s^2","9.8 m/s^2"],"answer":3,"explanation":"g is approximately 9.8 m/s^2 — used throughout the course."}]}'::jsonb, null, 10),
  (2, 'Units, measurement, and unit conversion', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the SI base units, use common prefixes, and convert between units by cancelling. Warm-up: from the diagnostic, which unit measures mass — the kilogram or the newton?"},{"heading":"The idea","text":"Physics measures the world with the SI system. The three base units you''ll use most are the *meter* (m) for length, the *kilogram* (kg) for mass, and the *second* (s) for time. Prefixes scale them: kilo- means 1000 (1 km = 1000 m), centi- means one hundredth (1 cm = 0.01 m), and milli- means one thousandth (1 mm = 0.001 m). To convert, multiply by a fraction equal to 1, arranged so the unwanted unit cancels. For example, 90 km/h × (1000 m / 1 km) × (1 h / 3600 s) = 90 × 1000 / 3600 = 25 m/s."},{"heading":"Worked examples","text":"1) Convert 5 km to meters: 5 × 1000 = 5000 m. 2) Convert 2.5 hours to seconds: 2.5 × 3600 = 9000 s. 3) A rug is 3 m by 4 m; its area is 3 × 4 = 12 m^2 (note the units multiply too). 4) Convert 72 km/h to m/s: 72 × 1000 / 3600 = 20 m/s."},{"heading":"Your turn","text":"Convert each, then check: (1) 36 km/h to m/s; (2) 500 cm to m; (3) 3 kg to grams; (4) 1.5 minutes to seconds; (5) 250 ms to seconds. Answers: (1) 36000/3600 = 10 m/s; (2) 5 m; (3) 3000 g; (4) 90 s; (5) 0.25 s."},{"heading":"Common mistakes & exit ticket","text":"Mistake: writing the conversion fraction upside down so units don''t cancel — always let the old unit sit opposite itself. Mistake: confusing mass (kg) with weight (a force in newtons). Exit: (a) Convert 18 km/h to m/s. (b) How many millimeters are in 1 m? Answers: 18000/3600 = 5 m/s; 1000 mm."}]}'::jsonb, 'Cancel units like fractions: km/h × (1000 m / 3600 s) leaves m/s.', 12),
  (3, 'Describing motion: velocity and acceleration', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell velocity from acceleration and use the constant-acceleration equations. Warm-up: which quantity carries a direction — speed or velocity?"},{"heading":"The idea","text":"*Velocity* is how fast position changes, with a direction; *acceleration* is how fast velocity changes. For motion with constant acceleration a, final velocity is v = v0 + a·t, and distance traveled from rest is (1/2)·a·t^2. Worked: a car starts from rest (v0 = 0) and accelerates at 2 m/s^2 for 5 s. Its speed is v = 0 + 2 × 5 = 10 m/s, and it covers (1/2) × 2 × 5^2 = (1/2) × 2 × 25 = 25 m."},{"heading":"Worked examples","text":"1) Free fall: an object is dropped (v0 = 0) with g = 9.8 m/s^2. After 3 s its speed is 9.8 × 3 = 29.4 m/s, and it has fallen (1/2) × 9.8 × 3^2 = 4.9 × 9 = 44.1 m. 2) Average velocity: a runner covers 100 m in 4 s, so the average is 100 / 4 = 25 m/s. 3) Braking: a car at 20 m/s decelerates at 4 m/s^2. Time to stop is 20 / 4 = 5 s, and stopping distance is v^2 / (2a) = 400 / 8 = 50 m."},{"heading":"Your turn","text":"Solve, then check: (1) a cyclist goes 0 to 12 m/s in 4 s — acceleration? (2) a car at 15 m/s accelerates 2 m/s^2 for 3 s — final speed? (3) an object dropped from rest, g = 9.8 — speed after 2 s? (4) a runner covers 200 m in 25 s — average speed? (5) a car slows from 30 m/s to 0 in 6 s — acceleration? Answers: (1) 12/4 = 3 m/s^2; (2) 15 + 2×3 = 21 m/s; (3) 9.8×2 = 19.6 m/s; (4) 200/25 = 8 m/s; (5) -30/6 = -5 m/s^2."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating speed (a number) and velocity (number plus direction) as the same. Mistake: thinking constant velocity requires a force — with zero acceleration the net force is zero. Exit: (a) With v0 = 0 and a = 10 m/s^2, find v after 3 s. (b) How far does a dropped object fall in the first 1 s (g = 9.8)? Answers: 10×3 = 30 m/s; (1/2)×9.8×1^2 = 4.9 m."}]}'::jsonb, 'For constant acceleration: v = v0 + a·t and distance = v0·t + (1/2)·a·t^2.', 13),
  (4, 'Forces and Newton''s laws', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"State Newton''s three laws and use F = ma to find force, mass, or acceleration. Warm-up: what does the F in F = ma stand for — one force, or the net of all forces?"},{"heading":"The idea","text":"Newton''s *first law* (inertia): an object keeps its velocity unless a net force acts. The *second law*: net force equals mass times acceleration, F = m·a. The *third law*: every action has an equal and opposite reaction. Force is measured in newtons (N), where 1 N = 1 kg·m/s^2. Worked: a net force of 10 N acts on a 2 kg block, so its acceleration is a = F / m = 10 / 2 = 5 m/s^2."},{"heading":"Worked examples","text":"1) Weight: a 5 kg bag has weight W = m·g = 5 × 9.8 = 49 N. 2) Accelerating a car: to give a 1000 kg car an acceleration of 3 m/s^2 needs F = 1000 × 3 = 3000 N. 3) Combining forces: on a 3 kg cart, 20 N pushes right and 8 N pulls left, so the net force is 20 - 8 = 12 N and the acceleration is 12 / 3 = 4 m/s^2 to the right."},{"heading":"Your turn","text":"Solve, then check: (1) net force 50 N on a 10 kg mass — acceleration? (2) mass 4 kg, acceleration 2.5 m/s^2 — force? (3) weight of a 20 kg object (g = 9.8)? (4) a 60 N force gives 12 m/s^2 — mass? (5) a 2 kg object feels 6 N right and 2 N left — acceleration? Answers: (1) 50/10 = 5 m/s^2; (2) 4×2.5 = 10 N; (3) 20×9.8 = 196 N; (4) 60/12 = 5 kg; (5) net 4 N / 2 = 2 m/s^2."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking heavier objects always fall faster — ignoring air, all objects fall at the same g. Mistake: putting a single force into F = ma instead of the net force. Exit: (a) Find F for m = 3 kg and a = 4 m/s^2. (b) Find the weight of a 10 kg object (g = 9.8). Answers: 3×4 = 12 N; 10×9.8 = 98 N."}]}'::jsonb, 'F = m·a, where F is the NET force; an object''s weight is W = m·g.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Convert 36 km/h to m/s.","options":["6 m/s","10 m/s","36 m/s","100 m/s"],"answer":1,"explanation":"36000 m / 3600 s = 10 m/s."},{"prompt":"A car starts from rest and accelerates at 2 m/s^2 for 4 s. Its final speed is…","options":["2 m/s","4 m/s","8 m/s","16 m/s"],"answer":2,"explanation":"v = 0 + 2 × 4 = 8 m/s."},{"prompt":"What net force gives a 5 kg mass an acceleration of 3 m/s^2?","options":["1.7 N","8 N","15 N","0.6 N"],"answer":2,"explanation":"F = m·a = 5 × 3 = 15 N."},{"prompt":"The weight of a 10 kg object (g = 9.8 m/s^2) is…","options":["1 N","10 N","98 N","980 N"],"answer":2,"explanation":"W = m·g = 10 × 9.8 = 98 N."},{"prompt":"An object dropped from rest falls for 2 s (g = 9.8 m/s^2). Its speed is…","options":["4.9 m/s","9.8 m/s","19.6 m/s","39.2 m/s"],"answer":2,"explanation":"v = g·t = 9.8 × 2 = 19.6 m/s."},{"prompt":"Which quantity has both a size and a direction?","options":["speed","distance","velocity","mass"],"answer":2,"explanation":"Velocity is a vector; speed, distance, and mass are scalars."}]}'::jsonb, null, 8),
  (6, 'Energy and work', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute work, kinetic and potential energy, and power. Warm-up: if you hold a heavy box perfectly still, how much work are you doing on it?"},{"heading":"The idea","text":"*Work* is energy transferred when a force moves an object along its direction: W = F·d, measured in joules (J). *Kinetic energy* — energy of motion — is (1/2)·m·v^2. *Potential energy* from height is m·g·h. *Power* is how fast work is done, P = W / t, in watts (W). Worked: push a cart with 10 N over 3 m and you do W = 10 × 3 = 30 J of work."},{"heading":"Worked examples","text":"1) Kinetic energy: a 2 kg ball moving at 4 m/s has KE = (1/2) × 2 × 4^2 = (1/2) × 2 × 16 = 16 J. 2) Potential energy: a 5 kg box lifted to 10 m has PE = 5 × 9.8 × 10 = 490 J. 3) Power: a motor that does 100 J of work in 5 s delivers P = 100 / 5 = 20 W."},{"heading":"Your turn","text":"Solve, then check: (1) a 25 N force over 4 m — work? (2) KE of a 3 kg object at 2 m/s? (3) PE of a 2 kg object at 5 m (g = 9.8)? (4) 200 J of work done in 10 s — power? (5) KE of a 1 kg object at 10 m/s? Answers: (1) 25×4 = 100 J; (2) (1/2)×3×2^2 = 6 J; (3) 2×9.8×5 = 98 J; (4) 200/10 = 20 W; (5) (1/2)×1×10^2 = 50 J."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking holding a weight still does work — with no displacement, W = F·d = 0. Mistake: forgetting that kinetic energy grows with the *square* of speed, so doubling speed quadruples KE. Exit: (a) Work of a 5 N force over 2 m? (b) KE of a 2 kg object at 3 m/s? Answers: 5×2 = 10 J; (1/2)×2×3^2 = 9 J."}]}'::jsonb, 'Work W = F·d; kinetic energy = (1/2)·m·v^2; power = work / time.', 13),
  (7, 'Momentum and collisions', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Compute momentum and impulse and apply conservation of momentum. Warm-up: which is harder to stop — a 1 kg ball at 10 m/s or a 10 kg cart at 1 m/s? (Compute the momentum of each.)"},{"heading":"The idea","text":"*Momentum* is mass times velocity, p = m·v, measured in kg·m/s, and it points the way the object moves. *Impulse* — a force applied over time, F·t — equals the change in momentum. In an isolated system (no outside forces) total momentum is *conserved*: the total before a collision equals the total after. Worked: a 2 kg cart at 3 m/s has momentum p = 2 × 3 = 6 kg·m/s. (The warm-up: both objects above have 10 kg·m/s, so they are equally hard to stop.)"},{"heading":"Worked examples","text":"1) Impulse: a 10 N force acting for 2 s changes momentum by F·t = 10 × 2 = 20 kg·m/s. 2) Sticky collision: a 2 kg cart at 4 m/s strikes a stationary 2 kg cart and they lock together. Total momentum stays 2 × 4 = 8 kg·m/s, now carried by 4 kg, so the shared speed is 8 / 4 = 2 m/s. 3) A 1000 kg car at 20 m/s carries momentum 1000 × 20 = 20000 kg·m/s."},{"heading":"Your turn","text":"Solve, then check: (1) momentum of a 5 kg object at 4 m/s? (2) impulse of an 8 N force over 3 s? (3) momentum of a 3 kg object at 6 m/s? (4) a 2 kg cart at 5 m/s sticks to a stationary 3 kg cart — final speed? (5) momentum of a 0.5 kg ball at 10 m/s? Answers: (1) 5×4 = 20 kg·m/s; (2) 8×3 = 24 kg·m/s; (3) 3×6 = 18 kg·m/s; (4) total 10 kg·m/s / 5 kg = 2 m/s; (5) 0.5×10 = 5 kg·m/s."},{"heading":"Common mistakes & exit ticket","text":"Mistake: forgetting momentum is a vector — opposite directions can cancel. Mistake: thinking speed alone tells you momentum; a small fast object can match a large slow one. Exit: (a) Momentum of a 4 kg object at 3 m/s? (b) Impulse of a 5 N force over 2 s? Answers: 4×3 = 12 kg·m/s; 5×2 = 10 kg·m/s."}]}'::jsonb, 'Momentum p = m·v is conserved in an isolated collision; impulse = F·t = change in p.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"velocity","translation":"the rate of change of position, including direction (a vector)","example":"A car moving at 20 m/s north has a velocity, not just a speed."},{"term":"acceleration","translation":"the rate of change of velocity over time","example":"Dropping from rest, an object accelerates at about 9.8 m/s^2."},{"term":"force","translation":"a push or pull, measured in newtons; net force equals mass times acceleration (F = m·a)","example":"A 10 N net force on a 2 kg block produces 5 m/s^2."},{"term":"work","translation":"energy transferred when a force moves an object along its direction (W = F·d), measured in joules","example":"Pushing with 10 N over 3 m does 30 J of work."},{"term":"momentum","translation":"mass times velocity (p = m·v); conserved in isolated collisions","example":"A 2 kg cart at 3 m/s has 6 kg·m/s of momentum."},{"term":"frequency","translation":"the number of wave cycles per second, measured in hertz (Hz)","example":"A sound wave at 440 Hz completes 440 cycles each second."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"How much work is done by a 20 N force acting over 5 m?","options":["4 J","25 J","100 J","0.25 J"],"answer":2,"explanation":"W = F·d = 20 × 5 = 100 J."},{"prompt":"The kinetic energy of a 2 kg object moving at 3 m/s is…","options":["3 J","6 J","9 J","18 J"],"answer":2,"explanation":"KE = (1/2)·m·v^2 = 0.5 × 2 × 9 = 9 J."},{"prompt":"The momentum of a 4 kg object moving at 5 m/s is…","options":["20 kg·m/s","9 kg·m/s","40 kg·m/s","1.25 kg·m/s"],"answer":0,"explanation":"p = m·v = 4 × 5 = 20 kg·m/s."},{"prompt":"The potential energy of a 3 kg object at a height of 10 m (g = 9.8) is…","options":["30 J","98 J","294 J","300 J"],"answer":2,"explanation":"PE = m·g·h = 3 × 9.8 × 10 = 294 J."},{"prompt":"If 150 J of work is done in 5 s, the power delivered is…","options":["30 W","150 W","750 W","0.03 W"],"answer":0,"explanation":"P = W / t = 150 / 5 = 30 W."},{"prompt":"In an isolated collision, which quantity is conserved?","options":["temperature","total momentum","applied force","volume"],"answer":1,"explanation":"With no outside forces, total momentum before equals total momentum after."}]}'::jsonb, null, 8),
  (10, 'Applied project: model a real motion', 'writing', '{"sections":[{"heading":"The task","text":"Choose one everyday motion you can observe — a car pulling away from a stop, a ball rolling down a ramp, a cyclist braking, or an elevator starting up. You will not need lab equipment; you''ll build a quantitative model of it using the tools from this course and check that your numbers are physically sensible."},{"heading":"Milestones","text":"1) Describe the motion and estimate the starting and ending speeds (in m/s) and the time it takes. 2) Compute the acceleration using a = (v - v0) / t. 3) Estimate the moving mass (in kg) and compute the net force with F = m·a and the momentum with p = m·v. 4) Compute the kinetic energy (1/2)·m·v^2 at the end, and state one energy source or sink (engine, gravity, brakes, friction). 5) Convert at least one of your speeds between km/h and m/s to show the units are consistent."},{"heading":"Self-check rubric","text":"Check each: every quantity carries a unit (m/s, kg, N, J, kg·m/s); the acceleration sign matches whether the object sped up or slowed down; F = m·a, KE = (1/2)·m·v^2, and p = m·v are applied correctly; the numbers are realistic (a walking pace is ~1.4 m/s, a highway car ~30 m/s); and your km/h-to-m/s conversion uses the factor 1000/3600. If all five hold, you have modeled the motion like a physicist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000005' and l.position = v.pos
);
